{
  "root": "main_stack",
  "state": {
    "itineraryDays": [
      {
        "dayDate": "September 10",
        "dayTitle": "Arrival & Eiffel Tower Grandeur",
        "morningActivity": "Arrive in Paris, check into your hotel, and settle in. Take a leisurely stroll around Île de la Cité.",
        "afternoonActivity": "Head to the Eiffel Tower. Pre-book tickets for summit access if desired, or enjoy the views from the Champ de Mars.",
        "dinnerSuggestion": "Enjoy a classic French bistro dinner in the 7th arrondissement near the Eiffel Tower, such as Le Bistrot Du Peintre for traditional fare.",
        "icon": "../assets/r_000795_01_4_geo-alt.svg"
      },
      {
        "dayDate": "September 11",
        "dayTitle": "Art, History & Champs-Élysées Charm",
        "morningActivity": "Immerse yourselves in art at the Louvre Museum. Focus on key masterpieces like the Mona Lisa and Venus de Milo (pre-book tickets).",
        "afternoonActivity": "Walk through the beautiful Tuileries Garden, then stroll up the Champs-Élysées to the Arc de Triomphe. Consider climbing to the top for panoramic city views.",
        "dinnerSuggestion": "Experience a delightful crêpe from a street vendor for a quick lunch, then for dinner, explore restaurants in the lively Latin Quarter, such as those along Rue Mouffetard.",
        "icon": "../assets/r_000795_01_4_geo-alt.svg"
      },
      {
        "dayDate": "September 12",
        "dayTitle": "Island History & Bohemian Heights",
        "morningActivity": "Visit the exterior of Notre Dame Cathedral and explore the charming streets of Île de la Cité. Afterwards, wander through the historic Latin Quarter, browsing bookstores and cafes.",
        "afternoonActivity": "Journey to the artistic neighborhood of Montmartre. Visit the Sacré-Cœur Basilica for stunning city views and explore Place du Tertre, where artists display their work.",
        "dinnerSuggestion": "Indulge in traditional French onion soup or steak frites at a cozy restaurant in Montmartre, such as Le Consulat, for a truly Parisian evening.",
        "icon": "../assets/r_000795_01_4_geo-alt.svg"
      },
      {
        "dayDate": "September 13",
        "dayTitle": "Departure",
        "morningActivity": "Enjoy a final Parisian breakfast at a local cafe. Depending on your flight schedule, you might have time for some last-minute souvenir shopping or a final walk along the Seine before heading to the airport.",
        "afternoonActivity": null,
        "dinnerSuggestion": null,
        "icon": null
      }
    ],
    "hotelDetails": [
      {
        "key": "Location",
        "value": "Perfect for exploring Notre Dame, Latin Quarter, and Seine River."
      },
      {
        "key": "Amenities",
        "value": "Comfortable rooms, often with classic Parisian decor."
      },
      {
        "key": "Price Range",
        "value": "Typically €160-€190/night in September (subject to change)."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "context_card",
        "hotel_card",
        "itinerary_title",
        "itinerary_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Parisian Adventure: 3-Day Itinerary",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Embark on a romantic 3-day journey through Paris, exploring iconic landmarks, charming neighborhoods, and delightful cuisine. This itinerary focuses on classic must-see attractions, ensuring a memorable first-time visit for two adults.",
        "variant": "body"
      },
      "children": []
    },
    "context_card": {
      "type": "Card",
      "props": {},
      "children": [
        "context_title",
        "context_dates_stack",
        "context_budget_stack"
      ]
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Context for Your Trip",
        "variant": "h3"
      },
      "children": []
    },
    "context_dates_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "context_dates_label",
        "context_dates_value"
      ]
    },
    "context_dates_label": {
      "type": "Text",
      "props": {
        "text": "Travel Dates:",
        "variant": "label"
      },
      "children": []
    },
    "context_dates_value": {
      "type": "Text",
      "props": {
        "text": "September 10-13, 2024 (3 nights, 3 full days of activities).",
        "variant": "body"
      },
      "children": []
    },
    "context_budget_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "context_budget_label",
        "context_budget_value"
      ]
    },
    "context_budget_label": {
      "type": "Text",
      "props": {
        "text": "Budget:",
        "variant": "label"
      },
      "children": []
    },
    "context_budget_value": {
      "type": "Text",
      "props": {
        "text": "Mid-range for hotel (€150-€200/night).",
        "variant": "body"
      },
      "children": []
    },
    "hotel_card": {
      "type": "Card",
      "props": {},
      "children": [
        "hotel_header_stack",
        "hotel_description",
        "hotel_details_table",
        "hotel_book_button"
      ]
    },
    "hotel_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "hotel_icon",
        "hotel_name"
      ]
    },
    "hotel_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000795_01_2_building.svg"
      },
      "children": []
    },
    "hotel_name": {
      "type": "Text",
      "props": {
        "text": "Hôtel Henri IV",
        "variant": "h2"
      },
      "children": []
    },
    "hotel_description": {
      "type": "Text",
      "props": {
        "text": "Consider staying at Hôtel Henri IV, located on Île de la Cité. It offers a charming, historic atmosphere and excellent access to many central attractions, often fitting within the specified budget for September.",
        "variant": "body"
      },
      "children": []
    },
    "hotel_details_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "key",
            "label": "Detail"
          },
          {
            "key": "value",
            "label": "Description"
          }
        ],
        "statePath": "/hotelDetails",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "hotel_book_button": {
      "type": "Button",
      "props": {
        "label": "Book Hôtel Henri IV"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.booking.com/hotel/fr/henri-iv.en.html"
          }
        }
      },
      "children": []
    },
    "itinerary_title": {
      "type": "Text",
      "props": {
        "text": "Your Paris Exploration Plan",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "dayDate",
            "label": "Date"
          },
          {
            "key": "dayTitle",
            "label": "Day"
          },
          {
            "key": "morningActivity",
            "label": "Morning"
          },
          {
            "key": "afternoonActivity",
            "label": "Afternoon"
          },
          {
            "key": "dinnerSuggestion",
            "label": "Dinner"
          },
          {
            "key": "icon",
            "label": "Icon"
          }
        ],
        "statePath": "/itineraryDays",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayTitle",
        "highlightColumns": [
          "dayDate"
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "paris_tourism_button",
        "louvre_tickets_button"
      ]
    },
    "paris_tourism_button": {
      "type": "Button",
      "props": {
        "label": "Official Paris Tourism Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.parisjetaime.com/eng/"
          }
        }
      },
      "children": []
    },
    "louvre_tickets_button": {
      "type": "Button",
      "props": {
        "label": "Book Louvre Tickets"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.louvre.fr/en/visit/plan-your-visit/tickets"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_1_button",
        "source_2_button"
      ]
    },
    "source_1_button": {
      "type": "Button",
      "props": {
        "label": "Paris Itinerary Guide (Travel + Leisure)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.travelandleisure.com/paris-itinerary-7507300"
          }
        }
      },
      "children": []
    },
    "source_2_button": {
      "type": "Button",
      "props": {
        "label": "Hôtel Henri IV on Booking.com"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.booking.com/hotel/fr/henri-iv.en.html"
          }
        }
      },
      "children": []
    }
  }
}
